    i := i + 1;
  }

  if found {
    var newItems := [];
    var j := 0;
    while j < |items|
      invariant 0 <= j <= |items|
      invariant |newItems| <= j
      decreases |items| - j
    {
      if items[j].id != id {
        newItems := newItems + [items[j]];
      }
      j := j + 1;
    }
    result := Success(newItems);
  } else {
    result := Failure("not found");
  }
