// Convert string to uppercase
function ToUpper(s: string): string
  decreases |s|
{
  if |s| == 0 then ""
  else if 'a' <= s[0] && s[0] <= 'z' then [CharToUpper(s[0])] + ToUpper(s[1..])
  else [s[0]] + ToUpper(s[1..])
}

// Convert lowercase char to uppercase
function CharToUpper(c: char): char
  ensures 'a' <= c <= 'z' ==> 'A' <= CharToUpper(c) <= 'Z'
{
  match c
  case 'a' => 'A'
  case 'b' => 'B'
  case 'c' => 'C'
  case 'd' => 'D'
  case 'e' => 'E'
  case 'f' => 'F'
  case 'g' => 'G'
  case 'h' => 'H'
  case 'i' => 'I'
  case 'j' => 'J'
  case 'k' => 'K'
  case 'l' => 'L'
  case 'm' => 'M'
  case 'n' => 'N'
  case 'o' => 'O'
  case 'p' => 'P'
  case 'q' => 'Q'
  case 'r' => 'R'
  case 's' => 'S'
  case 't' => 'T'
  case 'u' => 'U'
  case 'v' => 'V'
  case 'w' => 'W'
  case 'x' => 'X'
  case 'y' => 'Y'
  case 'z' => 'Z'
  case _ => c
}

// Reverse a string
function Reverse(s: string): string
  ensures |Reverse(s)| == |s|
  decreases |s|
{
  if |s| == 0 then ""
  else Reverse(s[1..]) + [s[0]]
}

